            target = {"x": t[0], "y": t[1]}
            break

    # If a target position is available, move towards it
    if isinstance(target, dict):
        tx = target.get("x", x)
        ty = target.get("y", y)
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        # Prefer diagonal if both diff exist
        if dx != 0 and dy != 0:
            return [dx, dy]
        if dx != 0:
            return [dx, 0]
        if dy != 0:
            return [0, dy]

    # Fallback heuristic: stay near center if no target
    cx = max(0, min(w - 1, w // 2))
    cy = max(0, min(h - 1, h // 2))
